const upsertCustomerByEmail = `-- name: UpsertCustomerByEmail :one
INSERT INTO customers (email, full_name, referral_code)
VALUES (lower($1::text), $2, $3)
ON CONFLICT (lower(email)) WHERE email IS NOT NULL DO UPDATE
    SET full_name = CASE WHEN customers.full_name = '' THEN EXCLUDED.full_name ELSE customers.full_name END
RETURNING id, phone, full_name, email, birth_date, referral_code, status, created_at, updated_at, deleted_at, (xmax = 0) AS inserted
`

type UpsertCustomerByEmailParams struct {
	Email        string
	FullName     string
	ReferralCode string
}

type UpsertCustomerByEmailRow struct {
	ID           uuid.UUID
	Phone        *string
	FullName     string
	Email        *string
	BirthDate    *time.Time
	ReferralCode string
	Status       string
	CreatedAt    time.Time
	UpdatedAt    time.Time
	DeletedAt    *time.Time
	Inserted     bool
}

// Crée le client s'il n'existe pas (connexion par e-mail).
func (q *Queries) UpsertCustomerByEmail(ctx context.Context, arg UpsertCustomerByEmailParams) (UpsertCustomerByEmailRow, error) {
	row := q.db.QueryRow(ctx, upsertCustomerByEmail, arg.Email, arg.FullName, arg.ReferralCode)
	var i UpsertCustomerByEmailRow
	err := row.Scan(
		&i.ID,
		&i.Phone,
		&i.FullName,
		&i.Email,
		&i.BirthDate,
		&i.ReferralCode,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.Inserted,
	)
	return i, err
}

